-- PROPOSED schema only. NOT applied. Requires dedicated, reviewed database and server-side access.
-- Avoid clinical information, PHI, or card details in this database until compliance review.
CREATE TABLE IF NOT EXISTS app_users (id uuid PRIMARY KEY, auth_subject text NOT NULL UNIQUE, role text NOT NULL CHECK (role IN ('member','ma','clinician','manager','owner')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS catalog_items (id uuid PRIMARY KEY, code text NOT NULL UNIQUE, kind text NOT NULL CHECK (kind IN ('membership','retail','service')), active boolean NOT NULL DEFAULT false, price_cents bigint NOT NULL CHECK (price_cents >= 0), currency char(3) NOT NULL DEFAULT 'usd', version integer NOT NULL CHECK (version > 0));
CREATE TABLE IF NOT EXISTS subscriptions (id uuid PRIMARY KEY, member_id uuid NOT NULL REFERENCES app_users(id), provider_subscription_id text UNIQUE, plan_code text NOT NULL, state text NOT NULL, period_start timestamptz, period_end timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS provider_events (event_id text PRIMARY KEY, event_type text NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz, processing_state text NOT NULL DEFAULT 'pending');
CREATE TABLE IF NOT EXISTS benefit_grants (id uuid PRIMARY KEY, subscription_id uuid NOT NULL REFERENCES subscriptions(id), period_key text NOT NULL, quantity integer NOT NULL CHECK(quantity > 0), valid_from timestamptz NOT NULL, expires_at timestamptz NOT NULL, status text NOT NULL, UNIQUE(subscription_id,period_key), CHECK(expires_at > valid_from));
CREATE TABLE IF NOT EXISTS benefit_redemptions (id uuid PRIMARY KEY, grant_id uuid NOT NULL REFERENCES benefit_grants(id), staff_id uuid NOT NULL REFERENCES app_users(id), idempotency_key text NOT NULL UNIQUE, state text NOT NULL CHECK(state IN ('confirmed','reversed')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS orders (id uuid PRIMARY KEY, member_id uuid REFERENCES app_users(id), status text NOT NULL, total_cents bigint NOT NULL CHECK(total_cents >= 0), idempotency_key text NOT NULL UNIQUE, provider_checkout_id text UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS money_events (id uuid PRIMARY KEY, order_id uuid REFERENCES orders(id), provider_event_id text UNIQUE, kind text NOT NULL, amount_cents bigint NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS expenses (id uuid PRIMARY KEY, category text NOT NULL, amount_cents bigint NOT NULL CHECK(amount_cents >= 0), vendor_code text, incurred_on date NOT NULL, created_by uuid NOT NULL REFERENCES app_users(id));
CREATE TABLE IF NOT EXISTS inventory_items (id uuid PRIMARY KEY, sku text NOT NULL UNIQUE, retail_price_cents bigint, acquisition_cost_cents bigint, reorder_threshold integer NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS inventory_movements (id uuid PRIMARY KEY, item_id uuid NOT NULL REFERENCES inventory_items(id), quantity_delta integer NOT NULL, reason text NOT NULL, created_by uuid NOT NULL REFERENCES app_users(id), occurred_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_events (id uuid PRIMARY KEY, actor_id uuid REFERENCES app_users(id), action text NOT NULL, entity_type text NOT NULL, entity_id uuid, created_at timestamptz NOT NULL DEFAULT now());
-- SECURITY GATE: no public grants. Implement least-privilege database roles and server-side authorization before deployment.
-- Atomic credit redemption MUST lock grant and count confirmed redemptions inside a single transaction.
-- Accounting schema requires additional review for reversals, payout reconciliation, taxes and financial controls.
